    /* ================= BIND RESULTS ================= */
    function BindSearchResult(response) {
        var resultsHtml = "";
        var $wrap = $("#DivListing .search-result-wrap");
        $("#DivListing .paginationBox").remove();

        //console.log("result Response=>",response);
        if (response && response.Results && response.Results.length > 0) {
            response.Results.forEach(function (item) {
                const formattedDateTime = item.content_createdate
                    ? new Date(item.content_createdate).toLocaleString("en-IN", {
                        day: "2-digit",
                        month: "short",
                        year: "numeric"
                        // hour: "2-digit",
                        // minute: "2-digit",
                        // hour12: true
                    })
                    : "";
                         resultsHtml += `
                    <div class="search-result-item">
                        <div class="search-result-top-wrap">
                        <div class="search-result-page-wrap">Published On: <span class="search-result-page">${formattedDateTime || ""}</span></div>
                            ${!item.source_url
                            ? `
                                <div class="search-result-page-wrap">Published In: <span class="search-result-page">${item.sectionname || ""}</span></div>`
                            : ''
                        }
                        </div>
                        ${item.source_url
                            ? `<div class="search-pdf"><p class="search-result-title"><a href="${item.source_url}" target="_blank">${item.description || ""}</a></p><a class="period-size" href="${item.source_url}" target="_blank"><span class="file-icon" ><img src="/images/pdf.svg" alt="PDF Icon" />  ${Number(item.pdf_size) >= 1024 ? ((v => (v - Math.floor(v) >= 0.5 ? Math.ceil(v) : Math.floor(v)))(Number(item.pdf_size) / 1024)) + " MB " : ((v => (v - Math.floor(v) >= 0.5 ? Math.ceil(v) : Math.floor(v)))(Number(item.pdf_size))) + " KB "} </span></a></div>`
                            // : `<span class="search-result-title">${item.title || ""}</span>`
                            : `<a class="search-result-title" target="_blank" data-manageby="${item.manageby}" data-section="${item.sectionname}" data-id="${item.linkid}">${item.title || ""}</a>
                                <div class="search-result-sec-text">${item.description || ""}</div>`
                        }
                    </div>`;
            });

            $wrap.html(resultsHtml).show();

            $("#DivListing").append(renderPagination(response.Page, response.TotalPages));
        } else {
            $wrap.hide().html("");
            $("#DivListing");
        }

        bindPaginationEvents();
    }

