    /* ================Date Validation===============*/

    $(document).on("input", "#daterange", function () {

        var dateRange = $(this).val().trim();
        var $error = $(".errorValidation");

        $error.text(""); // Clear previous error

        if (!dateRange.includes(" - ")) return;

        var dates = dateRange.split(" - ");
        if (dates.length !== 2) return;

        var startParts = dates[0].split("/");
        var endParts = dates[1].split("/");

        if (startParts.length !== 3 || endParts.length !== 3) return;

        var startDay = parseInt(startParts[0]);
        var startMonth = parseInt(startParts[1]);
        var startYear = parseInt(startParts[2]);

        var endDay = parseInt(endParts[0]);
        var endMonth = parseInt(endParts[1]);
        var endYear = parseInt(endParts[2]);

        // ✅ Month validation
        if (startMonth < 1 || startMonth > 12 || endMonth < 1 || endMonth > 12) {
            $error.text("Please enter a valid date format.");
            $(this).val("");
            return;
        }

        // ✅ Day validation
        if (startDay < 1 || startDay > 31 || endDay < 1 || endDay > 31) {
            $error.text("Please enter a valid date format.");
            $(this).val("");
            return;
        }

        var startDate = new Date(startYear, startMonth - 1, startDay);
        var endDate = new Date(endYear, endMonth - 1, endDay);

        if (startDate > endDate) {
            $error.text("Please enter a valid date format.");
            $(this).val("");
            return;
        }
    });


