        $("#totalResultCount").show();
        $("#ResultMessage").hide();

        if (daterange) {
            var dates = daterange.split(" - ");
            fromDate = convertDateFormat(dates[0]);
            toDate = convertDateFormat(dates[1]);
        }

        function convertDateFormat(dateStr) {
            var parts = dateStr.split("/");
            return parts[2] + "-" + parts[1] + "-" + parts[0];
        }

        var selectedSections = updateSectionButtonText();
        var isPdfData = $("#lstBtn1").val();
        //var ExactSearch = false;
