        // var storedValue = localStorage.getItem("searchText");

        // if (storedValue) {
        //     $("#searchResults").val(storedValue);
        //     $("#currentPage").val(storedValue);
        // }

        // 2️⃣ Get search text
        var searchText = $("#searchResults").val().trim();

        if (searchText) {
            // If user typed something
            $("#currentPage").val(searchText);

            //localStorage.setItem("searchText", searchText);
        } else {
            // Fallback to hidden field value
            searchText = $("#currentPage").val();
        }


        var AdvanceSearchBy = $('#chkTitleOnly').is(':checked');
        var AdvsearchBy = "";

        if (AdvanceSearchBy == true) {

            if (PdfData == true) {
                AdvsearchBy = "title+content";
            }
            else {
                AdvsearchBy = "title";
            }

        }
        else {
            AdvsearchBy = "title+content";
        }

        //var title = null;
        //var content = null;
        // var AdvsearchBy = "";

        // if (AdvanceSearchBy === "title") {
        //     AdvsearchBy = "title";
