        // else if (AdvanceSearchBy === "content")
        // {
        //     AdvsearchBy = "content";
        // }
        // else {
        //     AdvsearchBy = "title+content";
        // }

        var filterwithkeyword = searchText || "";

        $("#searchKeyword").text(filterwithkeyword);
        $("#btnSearch").val(filterwithkeyword);
        var url = '/FrontEnd/AdvanceSearchDetails';



        var requestModel = {
            searchType: 1,
            searchText: filterwithkeyword,
            sections: selectedSections,
            tags: TagFilter,
            fromDate: fromDate || "",
            toDate: toDate || "",
            isExactSearch: ExactSearch,
            isPdfSearch: PdfData,
            page: page,
            pageSize: pageSize,
            sortBy: sortByText,
            searchBy: AdvsearchBy,
            resultFields: []
        };

        $.ajax({
            url: url,
            type: "POST",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            data: JSON.stringify(requestModel),
            success: function (response) {
                $("#totalResultCount").text(response.TotalHits);
