                        LoadTagsFromES(requestModel);
                    } else {
                        console.log("⚠️ NOT loading ES tags - ReloadTags:", reloadTags, "Keyword:", filterwithkeyword);
                    }
                }
            },
            error: function (xhr) {
                console.log("Error:", xhr.responseText);
            }
        });
